from z3 import *

s = Solver()
x = [Int(f'x_{i}') for i in range(1, 22)]

for i in range(21):
    s.add(And(x[i] >= 0, x[i] <= 2))

for j in range(3):
    s.add(Sum([If(x[i] == j, i + 1, 0) for i in range(21)]) == 77)

if s.check() == sat:
    m = s.model()
    print([m.evaluate(x[i]).as_long() for i in range(21)])
else:
    print("UNSAT")
